// Des: Unit tests for the task list JSON writer
// Flo: build Task values > write list > parse the JSON > assert keys
// I/O: Task list > JSON array text for GET /tasks
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const task = @import("sv-serv-task.zig");
const tszz = std.testing;
fn listOut(allo: std.mem.Allocator, list: []const stor.Task) !std.json.Value { var outz: std.Io.Writer.Allocating = .init(allo); try task.taskListWrit(allo, "", &outz.writer, list); return try std.json.parseFromSliceLeaky(std.json.Value, allo, outz.written(), .{}); }
test "an empty list is an empty JSON array" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try listOut(aren.allocator(), &.{}); try tszz.expect(root == .array); try tszz.expectEqual(@as(usize, 0), root.array.items.len); }
test "one cron task keeps its fields and leaves unset optional keys out" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try listOut(aren.allocator(), &.{.{ .id = "nightly", .type = "cron", .sche = "0 2 * * *", .run = "echo x" }}); try tszz.expectEqual(@as(usize, 1), root.array.items.len); const obj = root.array.items[0].object; try tszz.expectEqualStrings("nightly", obj.get("id").?.string); try tszz.expectEqualStrings("cron", obj.get("type").?.string); try tszz.expectEqualStrings("0 2 * * *", obj.get("sche").?.string); try tszz.expectEqualStrings("shell", obj.get("kind").?.string); try tszz.expect(obj.get("on").?.bool); for ([_][]const u8{ "dela", "plus", "try", "tmo", "cwd", "shell", "lock" }) |keyz| try tszz.expect(obj.get(keyz) == null); }
test "optional numbers and flags are written when set, and an off task says on false" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try listOut(aren.allocator(), &.{.{ .id = "a", .type = "hand", .on = false, .run = "x", .dela = 7, .@"try" = 3, .tmo = 90, .noLog = true }}); const obj = root.array.items[0].object; try tszz.expect(!obj.get("on").?.bool); try tszz.expectEqual(@as(i64, 7), obj.get("dela").?.integer); try tszz.expectEqual(@as(i64, 3), obj.get("try").?.integer); try tszz.expectEqual(@as(i64, 90), obj.get("tmo").?.integer); try tszz.expect(obj.get("noLog").?.bool); }
test "quotes, backslashes and unicode in text fields survive the round trip, order is kept" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try listOut(aren.allocator(), &.{ .{ .id = "q\"b\\c", .type = "hand", .run = "x", .cwd = "C:\\a b\\é" }, .{ .id = "second", .type = "hand", .run = "y" } }); try tszz.expectEqual(@as(usize, 2), root.array.items.len); try tszz.expectEqualStrings("q\"b\\c", root.array.items[0].object.get("id").?.string); try tszz.expectEqualStrings("C:\\a b\\é", root.array.items[0].object.get("cwd").?.string); try tszz.expectEqualStrings("second", root.array.items[1].object.get("id").?.string); }
